def minSemestersWithLimit(n, relations, k):
    pre = [0] * n
    for a, b in relations:
        pre[b] |= 1 << a
    full = (1 << n) - 1
    pc = [0] * (1 << n)
    for i in range(1, 1 << n):
        pc[i] = pc[i >> 1] + (i & 1)
    INF = 10 ** 9
    dp = [INF] * (1 << n)
    dp[0] = 0
    for mask in range(1 << n):
        d = dp[mask]
        if d == INF:
            continue
        avail = 0
        for v in range(n):
            if not (mask >> v) & 1 and pre[v] & ~mask == 0:
                avail |= 1 << v
        if pc[avail] <= k:
            nm = mask | avail
            if d + 1 < dp[nm]:
                dp[nm] = d + 1
        else:
            sub = avail
            while sub:
                if pc[sub] == k:
                    nm = mask | sub
                    if d + 1 < dp[nm]:
                        dp[nm] = d + 1
                sub = (sub - 1) & avail
    return dp[full]
